type User = { name: string; role: 'user' | 'admin' };
type Admin = User & { role: 'admin' };

const users: User[] = [
  { name: 'Ada', role: 'admin' },
  { name: 'Bob', role: 'user' },
];

const admins = users.filter((u): u is Admin => u.role === 'admin');
// admins: Admin[]

type LineItem = { sku: string; qty: number };

function totalQty(items: LineItem[]): number {
  return items.reduce<number>((sum, item) => sum + item.qty, 0);
}

function bySku(items: LineItem[]): Record<string, number> {
  return items.reduce<Record<string, number>>((acc, item) => {
    acc[item.sku] = (acc[item.sku] ?? 0) + item.qty;
    return acc;
  }, {});
}

